<style>
    .support-container {
        padding: 40px 0;
        background: var(--bg-color);
        min-height: calc(100vh - 200px);
    }
    .page-header { margin-bottom: 40px; }
    .page-header h1 { font-size: 32px; font-weight: 700; margin-bottom: 10px; }
    .page-header p { color: var(--text-secondary); font-size: 18px; }
    .text-center { text-align: center; }

    .contact-grid {
        display: grid;
        grid-template-columns: 2fr 1fr;
        gap: 30px;
        max-width: 900px;
        margin: 0 auto;
    }

    .contact-form-card, .contact-info-card {
        background: var(--card-bg);
        padding: 30px;
        border-radius: 16px;
        box-shadow: var(--shadow);
    }

    .form-group {
        margin-bottom: 20px;
    }
    .form-group label {
        display: block;
        font-weight: 600;
        margin-bottom: 8px;
");
            WriteLiteral(@"    }
    .form-control {
        width: 100%;
        padding: 12px;
        border: 2px solid var(--border-color);
        border-radius: 8px;
        font-family: inherit;
        font-size: 15px;
    }
    .form-control:focus {
        border-color: var(--primary-color);
        outline: none;
    }

    .btn-submit {
        width: 100%;
        padding: 14px;
        font-size: 16px;
        font-weight: 600;
        border: none;
        border-radius: 8px;
        cursor: pointer;
    }

    .contact-info-card h3 {
        margin-bottom: 25px;
        color: var(--primary-color);
        border-bottom: 1px solid var(--border-color);
        padding-bottom: 10px;
    }

    .info-block {
        display: flex;
        gap: 15px;
        margin-bottom: 25px;
        align-items: flex-start;
    }
    .info-block .icon {
        font-size: 24px;
    }

    ");
